def minOperations(self, front: List[int], back: List[int]) -> int:
    n = len(front)
    INF = float('inf')

    dp = [[INF]*2 for _ in range(n)]

    dp[0][0] = 0
    dp[0][1] = 0

    for i in range(1, n):
        for prev in range(2):
            prev_val = front[i-1] if prev == 0 else back[i-1]
            for cur in range(2):
                cur_val = front[i] if cur == 0 else back[i]

                if prev_val <= cur_val:
                    cost = dp[i-1][prev]

                    if prev != cur:
                        cost += 1

                    dp[i][cur] = min(dp[i][cur], cost)

    ans = min(dp[n-1])
    return ans if ans != INF else -1

